```

若 `setdiff()` 返回任何列名，就要先修正代码中的列名，或确认数据文件是否包含这些列。下面的写法在普通数据框上按银行分组插值，并在列名不匹配时明确报错：

```r
library(imputeTS)

data <- read.csv("VS.csv", sep = ",", header = TRUE)

vars <- c(
  "Qtrcret", "Qtrret", "Qtraret", "EVANetAssrt1", "EVATotAssrt1",
  "EVAps1", "EVArt1", "OpeEVArt1", "QtrFulTurnR", "PE", "PB", "PCF",
  "PS", "SN", "N10H", "IH", "LR", "LCR", "STD", "RF", "LNINC"
)

needed <- c("bankcode", "time", vars)
missing_cols <- setdiff(needed, names(data))
if (length(missing_cols) > 0) {
  stop("数据中缺少这些列：", paste(missing_cols, collapse = ", "))
}

data$time <- as.Date(data$time, format = "%Y/%m/%d")
if (anyNA(data$time)) {
  stop("time 中有日期无法按 %Y/%m/%d 解析；请检查原始日期格式。")
}

if (anyNA(data$bankcode)) {
  stop("bankcode 中存在 NA，请先处理后再分组插值。")
}
if (!all(vapply(data[vars], is.numeric, logical(1)))) {
  stop("待插值变量必须是数值型；请检查并转换相关列。")
}

# 按银行、日期排序，使插值顺序符合时间顺序
data <- data[order(data$bankcode, data$time), ]

for (id in unique(data$bankcode)) {
  idx <- which(data$bankcode == id)

  for (v in vars) {
    x <- data[[v]][idx]
    n_observed <- sum(!is.na(x))

    if (anyNA(x) && n_observed >= 3) {
      data[[v]][idx] <- na_interpolation(x, option = "spline")
    } else if (anyNA(x) && n_observed >= 2) {
      # 可用观测点太少时，用线性插值作为回退方案
      data[[v]][idx] <- na_interpolation(x, option = "linear")
    }
    # 观测值不足 2 个时不做插值，避免产生没有数据依据的填充值
  }
}

summary(data)
