    const result = findValueAtCoordinates(codes, 12, 3, 5, 6);

    // Imprimir o resultado
    std.debug.print("O código encontrado é: {}", .{result});
}

fn generateCodes() []uint64 {
    var codes := std.mem.Alloc(uint64, std.heap.allocator) ([]uint64) init {};
    var current_code : uint64 = 20151125;
    var i : usize = 0;

    while (i < 100) { // Supondo que queremos apenas os primeiros 100 códigos
        if (i == 0) {
            codes.append({})(.init(current_code));
        } else {
            current_code = (current_code * 252533) % 33354393;
            codes.append({})(.init(current_code));
        }
        i += 1;
    }

    return codes.;
}

fn findValueAtCoordinate(codes : []uint64, x : usize, y : usize) uint64 {
    for (0; x > 0 && y > 0; ) {
        x -= 1;
        y -= 1;
